        return h('tr', {}, h('td', {}, wi), h('td', {}, ps), h('td', {}, mi), h('td', {}, h('span', { class: 'cs-x is-visible', onclick: () => W((x) => { x.lexicon.splice(i, 1); }) }, '✕')));
