const PAGE_TWIPS = { '6x9': [8640, 12960, 1080], '5x8': [7200, 11520, 1008], '5.5x8.5': [7920, 12240, 1080], letter: [12240, 15840, 1440], a4: [11906, 16838, 1440] };
