    const copy = [`Copyright © ${m.copyright || new Date().getFullYear()} ${m.author}`, 'All rights reserved.', m.isbn ? `ISBN ${m.isbn}` : '', m.publisher ? `Published by ${m.publisher}` : '', m.draftLine || ''].filter(Boolean);
